changeSet.sql:

DROP TABLE if exists "Informacion Financiera" ;

CREATE TABLE "Informacion Financiera" (
    loan_id bigint PRIMARY KEY,
    ingresos  NUMERIC ,
    activos  NUMERIC,
    created_at TIMESTAMP,
    updated_at TIMESTAMP NULL
);


COMMENT ON COLUMN "Informacion Financiera".loan_id IS 'Identificador Unico Prestamo';
COMMENT ON COLUMN "Informacion Financiera".ingresos IS 'Ingresos';
COMMENT ON COLUMN "Informacion Financiera".activos IS 'Activos';
COMMENT ON COLUMN "Informacion Financiera".created_at IS 'Creado en';
COMMENT ON COLUMN "Informacion Financiera".updated_at IS 'Actualizado en';


